{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list):
        raise ValueError("nodes must be a list")
    if not isinstance(required_symbols, list) or not all(isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    required = set(required_symbols)
    by_id = {}
    original_ids = []
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable"):
            if field not in node:
                raise ValueError("node missing required field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        if not isinstance(node_id, str):
            raise ValueError("node id must be a string")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("node parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("node symbol must be a string")
        if not isinstance(depth, int):
            raise ValueError("node depth must be an integer")
        if not isinstance(removable, bool):
            raise ValueError("node removable must be a boolean")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        by_id[node_id] = node
        original_ids.append(node_id)

    retained = set(original_ids)
    removed_order = []

    def required_symbols_still_represented(after_removing=None):
        present = set()
        for nid in retained:
            if nid == after_removing:
                continue
            present.add(by_id[nid]["symbol"])
        return required.issubset(present)

    candidates = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id not in retained:
            continue
        if node["parent"] is None or node_id == "root":
            continue
        if not node["removable"]:
            continue
        if node["symbol"] in required:
            continue

        has_retained_child = False
        for other in nodes:
            if other["parent"] == node_id and other["id"] in retained:
                has_retained_child = True
                break
        if has_retained_child:
            continue

        if not required_symbols_still_represented(node_id):
            continue

        retained.remove(node_id)
        removed_order.append(node_id)

    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": sorted(retained),
    }
"}
